static std::string extraGalleryFixture(){std::ostringstream out;out<<"WOHGALLERY1 "<<mahoyo::extra::NativeHash<<" 401 1314\n";int name=0;for(int g=0;g<401;++g){int n=g<111?4:3;out<<"G "<<g<<' '<<n<<'\n';for(int v=0;v<n;++v){out<<"V "<<g<<' '<<v<<" \"img"<<std::setw(4)<<std::setfill('0')<<name++<<".mzp\" ";if(g==0)out<<(v==0?"10,11":v==1?"-":v==2?"12":"13");else out<<14;out<<'\n';}}return out.str();}
static std::string extraMusicFixture(){std::ostringstream out;out<<"WOHMUSIC1 "<<mahoyo::extra::NativeHash<<" 56\n";for(int i=0;i<56;++i)out<<"M "<<i<<' '<<i+2<<' '<<258+i<<" \"m"<<i<<".hw\" \"mu_text1_select_ja.cbg\" "<<(i%2)*528<<' '<<(i%14)*72<<" 528 72\n";return out.str();}
static void extraFixtureText(Fixture& f,const std::string& name,const std::string& value){archiveFixtureFile(f,"meta/"+name,{value.begin(),value.end()});}
static void prepareExtra(Fixture& f){
    woh_destroy(f.handle);f.handle=0;extraFixtureText(f,"gallery-catalog.tsv",extraGalleryFixture());extraFixtureText(f,"music-catalog.tsv",extraMusicFixture());
    extraFixtureText(f,"audio-loop-map.tsv","x_m64.hw 11664000 48000 2 1 648000 5400000\nm42.hw 5396032 48000 2 1 0 5264828\nm0.hw 48000 48000 2 1 200 40000\n");
    mahoyo::shared::State state;state.generation=40;state.variables.resize(4096);state.flags.resize(16384);for(int v:{10,11,258,259,261,321})state.flags[size_t(v)]=1;mahoyo::shared::write(f.root/"savedata/shared.whp",state);f.handle=woh_create(f.game.string().c_str());
}
static std::string extraJson(const std::string& state,const char* key,const char* next){auto start=state.find(std::string("\"")+key+"\":");check(start!=std::string::npos,"Extra snapshot field exists");start+=std::strlen(key)+3;return state.substr(start,state.find(std::string(",\"")+next+"\":",start)-start);}
static std::string galleryJsonOf(const std::string& state){return extraJson(state,"gallery","musicRoom");}
static std::string musicJsonOf(const std::string& state){return extraJson(state,"musicRoom","archive");}
static std::string galleryGroupOf(const std::string& state,int id){auto text=galleryJsonOf(state);auto at=text.find("\"id\":"+std::to_string(id)+",\"count\":");check(at!=std::string::npos,"gallery group exists");return text.substr(at,text.find('}',at)-at+1);}
static void extraCatalogContracts(){
    for(const char* locale:{"ja","en","zc","zt"}){
        auto text=extraMusicFixture();size_t at=0;const std::string from="_ja.cbg",to=std::string("_")+locale+".cbg";
        while((at=text.find(from,at))!=std::string::npos){text.replace(at,from.size(),to);at+=to.size();}
        std::istringstream input(text);check(mahoyo::extra::Music::parse(input).tracks.size()==56,"music accepts each shipped locale atlas without relaxing crop/track guards");
    }
    for(const char* bad:{"mu_text0_select_en.cbg","mu_text4_select_ja.cbg","mu_text1_select_ko.cbg","../mu_text1_select_en.cbg"})check(!mahoyo::extra::Music::atlasName(bad),"music locale support still rejects unknown pages, unsupported slots and paths");
    auto raw=extraGalleryFixture();std::istringstream g(raw);auto gallery=mahoyo::extra::Gallery::parse(g);check(gallery.groups.size()==401&&gallery.groups.front().variants.size()==4,"complete gallery parses exact group/variant structure");std::vector<uint8_t> flags(2048);std::set<std::string> seen;flags[10]=1;check(!gallery.unlocked(gallery.groups[0].variants[0],flags,seen),"CG special condition is AND");flags[11]=1;check(gallery.unlocked(gallery.groups[0].variants[0],flags,seen),"all CG special flags unlock that variant");check(!gallery.unlocked(gallery.groups[0].variants[1],flags,seen),"ordinary CG is not unlocked merely by neighbor variant");seen.insert("img0001.mzp");check(gallery.unlocked(gallery.groups[0].variants[1],flags,seen),"ordinary CG uses exact seen filename");for(int f:{128,65,73,72,206,129,130,131,132,133,134})flags[size_t(f)]=1;check(gallery.unlocked(gallery.groups[0].variants[3],flags,{}),"completion eleven flags unlock all CG variants");flags[128]=0;check(!gallery.unlocked(gallery.groups[0].variants[3],flags,{}),"one missing completion flag does not unlock a locked variant");
    for(auto bad:{raw.substr(0,raw.rfind("V ")),raw+"G 0 1\n"}){bool rejected=false;try{std::istringstream x(bad);mahoyo::extra::Gallery::parse(x);}catch(...){rejected=true;}check(rejected,"incomplete/duplicate gallery metadata rejects");}
    std::istringstream m(extraMusicFixture());auto music=mahoyo::extra::Music::parse(m);flags.assign(2048,0);flags[258]=flags[259]=flags[261]=1;check(music.adjacent(1,1,flags)==3&&music.adjacent(0,-1,flags)==3&&music.adjacent(3,1,flags)==0,"music order skips locked rows and wraps");check(music.unlocked(*music.find(1),flags)&&!music.unlocked(*music.find(2),flags),"music heard flag is separate per native ID");
}
static void galleryRuntimeGatesAndReturn(){
    Program p;p.string("img0001");p.op(0x228);p.dialogue(0);p.op(0xf4);Fixture f(std::move(p));prepareExtra(f);f.command("textSpeed","0");f.command("action","start");auto state=f.command("title"),titleBgm=audioChannel(state,"bgm");auto common=mahoyo::shared::read(f.root/"savedata/shared.whp");state=f.command("galleryOpen");auto gen=uint64_t(number(galleryJsonOf(state),"id"));check(waiting(state,"gallery")&&!boolean(state,"canSave")&&number(state,"instructions")==0&&number(state,"nextTickMs")==0,"CG frontend owns no gameplay VM/save or idle tick");check(number(galleryGroupOf(state,0),"count")==2&&number(galleryGroupOf(state,1),"count")==0&&galleryGroupOf(state,1).find("preview")==std::string::npos,"only unlocked CG variants influence preview and count");check(number(audioChannel(state,"bgm"),"id")==number(titleBgm,"id"),"CG frontend retains active title BGM position");
    state=f.command("galleryAction",(std::to_string(gen+1)+" select 0").c_str());check(number(galleryJsonOf(state),"group")==-1,"stale gallery generation is inert");state=f.command("galleryAction",(std::to_string(gen)+" select 1").c_str());check(number(galleryJsonOf(state),"group")==-1,"locked CG groups cannot open");state=f.command("galleryAction",(std::to_string(gen)+" select 0").c_str());auto detail=galleryJsonOf(state);check(number(detail,"variant")==0&&detail.find("img0001.mzp")!=std::string::npos&&detail.find("img0002.mzp")==std::string::npos,"viewer receives unlocked variants only");state=f.command("galleryAction",(std::to_string(gen)+" next 0").c_str());check(number(galleryJsonOf(state),"variant")==1,"next selects next unlocked variant");state=f.command("galleryAction",(std::to_string(gen)+" variant 0 2").c_str());check(number(galleryJsonOf(state),"variant")==1,"locked variant cannot be selected by raw index");state=f.command("galleryAction",(std::to_string(gen)+" back").c_str());check(number(galleryJsonOf(state),"group")==-1&&number(galleryJsonOf(state),"focus")==0,"Back from viewer returns focused dense catalog");state=f.command("galleryAction",(std::to_string(gen)+" back").c_str());check(state.find("\"scene\":\"title\"")!=std::string::npos&&number(audioChannel(state,"bgm"),"id")==number(titleBgm,"id"),"catalog Back returns title without restarting its BGM");auto after=mahoyo::shared::read(f.root/"savedata/shared.whp");check(after&&common&&after->variables==common->variables&&after->flags==common->flags,"CG viewing does not invent new seen/heard/global progress");f.passed=true;
}
static void musicRuntimeTimingsAndCompletion(){
    Fixture f(appendProgram());prepareExtra(f);auto state=f.command("musicOpen");auto gen=uint64_t(number(musicJsonOf(state),"id"));check(waiting(state,"music")&&!boolean(state,"canSave")&&number(musicJsonOf(state),"selected")==0,"music opens at first unlocked native row without a game VM");f.command("tick","1000");state=f.command("tick","1283");check(number(audioChannel(state,"bgm"),"volume")>0,"title exit fade still exists at299ms");state=f.command("tick","1284");check(audioChannel(state,"bgm").find("\"path\":\"\"")!=std::string::npos&&number(state,"nextTickMs")==0,"music entry stops title cue at300ms then idles");
    state=f.command("musicAction",(std::to_string(gen)+" play 0").c_str());auto a=audioChannel(state,"bgm");check(a.find("m0.hw")!=std::string::npos&&!boolean(a,"loop")&&a.find("loopRegion")==std::string::npos&&number(a,"volume")==1&&number(a,"pan")==64,"music room uses native loop0 despite wrapper partial-loop metadata");auto first=uint64_t(number(a,"id"));state=f.command("musicAction",(std::to_string(gen)+" play 1").c_str());check(musicJsonOf(state).find("switching")!=std::string::npos&&audioChannel(state,"bgm").find("m0.hw")!=std::string::npos,"manual replacement keeps old track during native2000ms fade");f.command("tick","2000");state=f.command("tick","3983");check(audioChannel(state,"bgm").find("m0.hw")!=std::string::npos,"new track cannot start at1999ms");state=f.command("tick","3984");a=audioChannel(state,"bgm");check(a.find("m1.hw")!=std::string::npos&&musicJsonOf(state).find("playing")!=std::string::npos,"replacement starts at2000ms");auto second=uint64_t(number(a,"id"));state=f.command("audioEnded",("bgm "+std::to_string(first)).c_str());check(number(audioChannel(state,"bgm"),"id")==second,"stale end callback cannot advance MusicRoom");state=f.command("audioEnded",("bgm "+std::to_string(second)).c_str());a=audioChannel(state,"bgm");check(a.find("m3.hw")!=std::string::npos&&number(musicJsonOf(state),"row")==3,"one-shot completion immediately starts the next unlocked row");
    f.command("musicAction",(std::to_string(gen)+" repeat").c_str());auto third=uint64_t(number(a,"id"));state=f.command("audioEnded",("bgm "+std::to_string(third)).c_str());a=audioChannel(state,"bgm");check(a.find("m3.hw")!=std::string::npos&&number(a,"id")!=third&&!boolean(a,"loop"),"repeat restarts the same whole one-shot without enabling HW partial loop");state=f.command("musicAction",(std::to_string(gen)+" stop").c_str());check(number(musicJsonOf(state),"row")==-1,"manual stop clears playing row immediately");f.command("tick","5000");state=f.command("tick","6483");check(number(audioChannel(state,"bgm"),"volume")>0,"manual stop fades for1499ms");state=f.command("tick","6484");check(audioChannel(state,"bgm").find("\"path\":\"\"")!=std::string::npos&&number(state,"nextTickMs")==0,"manual stop completes at1500ms and removes polling");
    f.command("musicAction",(std::to_string(gen)+" play 0").c_str());state=f.command("musicAction",(std::to_string(gen)+" back").c_str());check(musicJsonOf(state).find("closing")!=std::string::npos,"music close remains an independent700ms phase");f.command("tick","7000");state=f.command("tick","7683");check(waiting(state,"music"),"close cannot expose title at699ms");state=f.command("tick","7684");a=audioChannel(state,"bgm");check(state.find("\"scene\":\"title\"")!=std::string::npos&&a.find("x_m64.hw")!=std::string::npos&&boolean(a,"loop")&&number(a,"startFrame")==648000,"700ms close restores actual title cue and its original partial loop");f.passed=true;
}
static void archiveCheckpointReturnHasNoPicker(){
    for(int selector=1;selector<=13;++selector){Fixture f(teatimeProgram(selector));prepareArchive(f);std::ostringstream map;map<<"WOHCHECKPOINT1 "<<mahoyo::extra::NativeHash<<" 13\n";for(int i=1;i<=13;++i){auto name="teatime"+std::to_string(i)+".chs";map<<"C "<<i<<" \""<<name<<"\"\n";Program target;target.image(1000,"BLACK");target.push(459);target.op(0xe1);target.push(0);target.op(0x251);target.dialogue(0);target.op(0xf4);archiveFixtureFile(f,"scripts/"+name,target.build());}extraFixtureText(f,"checkpoint-map.tsv",map.str());auto ready=readyTeatime(f);auto state=modalCommand(f,ready,"archive");auto gen=uint64_t(number(archiveObject(state),"id"));state=f.command("archiveBack",std::to_string(gen).c_str());check(waiting(state,"input")&&state.find("\"module\":\"teatime"+std::to_string(selector)+".chs\"")!=std::string::npos&&number(state,"z")==selector,"Back starts exactly the entry checkpoint as a fresh VM, not an invented13-item picker");f.command("save","2");InspectHost h;mahoyo::vm::Machine vm(h);vm.loadState(mahoyo::save::read(f.root/"savedata/slot2.whs").vm);check(vm.variable(8,true)==0&&vm.variable(459)==selector&&vm.variable(500)==0&&vm.variable(26)==0,"checkpoint request preserves Native mode0/shared8zero/local459 without replay markers");f.passed=true;}
}
static void musicRuntimeErrorCanExit(){Fixture f(appendProgram());prepareExtra(f);auto state=f.command("musicOpen");auto gen=uint64_t(number(musicJsonOf(state),"id"));state=f.command("musicAction",(std::to_string(gen)+" play 0").c_str());auto id=uint64_t(number(audioChannel(state,"bgm"),"id"));state=woh_command(f.handle,"audioError",("bgm "+std::to_string(id)+" synthetic decoder error").c_str());check(state.find("Audio playback failed")!=std::string::npos&&number(state,"nextTickMs")==0,"frontend decode errors stop timers rather than retry");state=f.command("musicAction",(std::to_string(gen)+" back").c_str());check(state.find("\"scene\":\"title\"")!=std::string::npos&&audioChannel(state,"bgm").find("x_m64.hw")!=std::string::npos,"error exit can restore Title without waiting on a disabled fatal-error timer");state=f.command("musicOpen");gen=uint64_t(number(musicJsonOf(state),"id"));state=f.command("musicAction",(std::to_string(gen)+" play 0").c_str());id=uint64_t(number(audioChannel(state,"bgm"),"id"));f.command("musicAction",(std::to_string(gen)+" back").c_str());state=woh_command(f.handle,"audioError",("bgm "+std::to_string(id)+" closing decoder error").c_str());check(musicJsonOf(state).find("idle")!=std::string::npos,"audio error during close restores an escapable frontend state");state=f.command("musicAction",(std::to_string(gen)+" back").c_str());check(state.find("\"scene\":\"title\"")!=std::string::npos,"late closing decoder error cannot trap disabled Back");f.passed=true;}
